<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Preview PDF | CourseUp</title><style>html,body{margin:0;background:#f8fafc;font-family:Arial}body{padding:16px}.toolbar{max-width:900px;margin:auto auto 16px;font-weight:bold}.pages{display:grid;gap:16px;justify-items:center}canvas{max-width:100%;height:auto;background:#fff;box-shadow:0 4px 18px #0f172a1f}.status{text-align:center;padding:48px;color:#64748b}</style></head><body><div class="toolbar">{{ $material->title }} <span id="status">Memuat preview...</span></div><div id="pages" class="pages"><div class="status">Memuat halaman PDF...</div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><script>const pdfBase64=@json($pdfBase64),pages=document.getElementById('pages'),status=document.getElementById('status');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';pdfjsLib.getDocument({data:Uint8Array.from(atob(pdfBase64),c=>c.charCodeAt(0))}).promise.then(async pdf=>{pages.innerHTML='';status.textContent=pdf.numPages+' halaman';for(let n=1;n<=pdf.numPages;n++){const p=await pdf.getPage(n),v=p.getViewport({scale:1.35}),c=document.createElement('canvas');c.width=v.width;c.height=v.height;pages.appendChild(c);await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise}}).catch(()=>{status.textContent='Gagal memuat';pages.innerHTML='<div class="status">Preview PDF gagal dimuat.</div>'});</script></body></html>